package pool

import (
	"context"
	"sync"
)

// Task представляет собой функцию, которая будет выполнена воркером.
// Она принимает контекст для управления отменой и возврата ошибки при сбое.
type Task func(ctx context.Context) error

// Pool — пул воркеров с ограничением параллелизма.
// Он позволяет отправлять задачи в канал и обрабатывать их фиксированным числом горутины-воркеров.
type Pool struct {
	// taskCh — канал, по которому передаются задачи на выполнение.
	// Его буферизация помогает избежать блокировки отправителя при кратковременных пиках нагрузки.
	taskCh chan Task

	// ctx — контекст, используемый для управления жизненным циклом пула.
	// При вызове Stop() этот контекст отменяется, что приводит к завершению всех воркеров.
	ctx    context.Context
	cancel context.CancelFunc

	// wg — WaitGroup для ожидания завершения всех воркеров при остановке пула.
	wg sync.WaitGroup

	// numWorkers — количество одновременно работающих воркеров (ограничение параллелизма).
	numWorkers int
}

// NewPool создаёт новый пул воркеров.
//
// Параметры:
//   - numWorkers: количество воркеров, которые будут работать параллельно.
//     Значение должно быть положительным; иначе возвращается ошибка.
//   - bufferSize: размер буфера канала задач. Если 0, используется небуферизованный канал.
//     Рекомендуется задавать значение > 0 для снижения вероятности блокировки отправителя.
//
// Возвращает указатель на готовый к работе пул и ошибку (если параметры некорректны).
func NewPool(numWorkers, bufferSize int) (*Pool, error) {
	if numWorkers <= 0 {
		return nil, ErrInvalidNumWorkers
	}

	// Создаём контекст с возможностью отмены.
	// cancel-функция будет вызвана при остановке пула.
	ctx, cancel := context.WithCancel(context.Background())

	// Определяем размер буфера канала.
	// Если bufferSize == 0, используем небуферизованный канал.
	bufSize := bufferSize
	if bufSize < 0 {
		bufSize = 0 // Защита от отрицательных значений
	}

	p := &Pool{
		taskCh:     make(chan Task, bufSize),
		ctx:        ctx,
		cancel:     cancel,
		numWorkers: numWorkers,
	}

	// Запускаем воркеров.
	p.startWorkers()

	return p, nil
}

// startWorkers запускает указанное количество горутины-воркеров.
// Каждый воркер бесконечно читает задачи из канала до тех пор, пока канал не будет закрыт
// или контекст не будет отменён.
func (p *Pool) startWorkers() {
	for i := 0; i < p.numWorkers; i++ {
		p.wg.Add(1)
		go p.worker(i)
	}
}

