//!
//! Позиционные аргументы — пути к входным файлам или директориям.

use std::path::PathBuf;
use std::process;

/// Ошибка парсинга аргументов командной строки.
#[derive(Debug)]
pub enum ParseError {
    /// Неизвестный флаг передан пользователем.
    UnknownFlag(String),
    /// Флагу не хватает значения (например, `--level` без числа).
    MissingValue(String),
    /// Значение уровня сжатия вне допустимого диапазона 1..=9.
    InvalidLevel(u32),
    /// Не задано ни одного входного файла/директории.
    NoInputFiles,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::UnknownFlag(flag) => write!(f, "Неизвестный флаг: {}", flag),
            ParseError::MissingValue(flag) => write!(f, "Флагу {} не хватает значения", flag),
            ParseError::InvalidLevel(level) => {
                write!(f, "Уровень сжатия должен быть в диапазоне 1..=9, получено: {}", level)
            }
            ParseError::NoInputFiles => write!(f, "Не указано ни одного входного файла"),
        }
    }
}

