// Возвращает строку со значением и булево значение, указывающее на успех операции.
func (c *Cache) Get(key string) (string, bool) {
    // Приобретаем блокировку для чтения (RLock), чтобы обеспечить безопасный доступ к данным
    // при одновременном чтении несколькими горутинами.
    c.mu.RLock()

    // Пытаемся получить элемент (e) из словаря items по указанному ключу.
    // Переменная ok будет true, если ключ найден, иначе false.
    e, ok := c.items[key]

    // Освобождаем блокировку для чтения (RUnlock), так как мы закончили чтение данных.
    c.mu.RUnlock()

    // Проверяем, был ли ключ найден (ok == true) И не истекло ли время жизни элемента.
    // time.Now().After(e.expires) возвращает true, если текущее время позже времени истечения срока действия.
    if !ok || time.Now().After(e.expires) {
        // Если ключ не найден или элемент устарел, возвращаем пустую строку и false.
        return "", false
    }

    // Если элемент найден и еще действителен, возвращаем его значение и true.
    return e.value, true
}
