/**
 * Создаёт дебаунс-обёртку для переданной функции.
 * 
 * @param fn - Функция, которую нужно обернуть в дебаунс.
 *             Ограничение: функция не должна возвращать значение (void).
 * @param ms - Задержка в миллисекундах, по истечении которой будет вызвана функция.
 * @returns Обёрнутая функция с теми же параметрами, что и исходная.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Изначально она не определена, так как таймер ещё не создан.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная.
  return (...args: Parameters<T>) => {
    // Если предыдущий таймер ещё активен — отменяем его.
    // Это обеспечивает "дебаунс": только последний вызов за период ms будет выполнен.
    if (timer) clearTimeout(timer);

    // Устанавливаем новый таймер на заданную задержку.
    // По истечении времени ms будет вызвана исходная функция с последними переданными аргументами.
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

