/**
 * Универсальная функция для повторного выполнения блока кода при возникновении IOException.
 *
 * @param times Количество попыток выполнения блока (включая первую).
 * @param block Лямбда-функция, содержащая код, который нужно выполнить с возможностью повтора.
 * @return Результат выполнения блока, если он завершился успешно.
 * @throws IOException Если все попытки завершились исключением IOException.
 * @throws IllegalStateException Если передано количество попыток <= 0.
 */
fun <T> retry(times: Int, block: () -> T): T {
    // Переменная для хранения последнего возникшего исключения IOException.
    // Изначально она null, так как исключение еще не происходило.
    var last: Throwable? = null

    // Цикл повторяет выполнение блока `times` раз.
    repeat(times) {
        try {
            // Пытаемся выполнить переданный блок кода.
            // Если выполнение успешное — сразу возвращаем результат функции.
            return block()
        } catch (e: IOException) {
            // Если произошло исключение IOException:
            // сохраняем его в переменную `last`, чтобы бросить его позже,
            // если все попытки исчерпаны.
            last = e
        }
    }

    // Если цикл завершился без возврата результата (т.е. все попытки провалились),
    // бросаем последнее сохраненное исключение.
    // Оператор `?:` гарантирует, что если `last` равен null (что возможно только при times <= 0),
    // будет выброшено IllegalStateException с понятным сообщением.
    throw last ?: IllegalStateException("times must be > 0")
}
```

