// Get возвращает значение из кэша по указанному ключу.
//
// Функция выполняет чтение из кэша с использованием блокировки чтения (RLock),
// что позволяет нескольким горутинам одновременно читать данные без взаимной блокировки.
//
// Параметры:
//   - key: строковый ключ, по которому ищется значение в кэше.
//     Ключ должен быть непустым; пустая строка будет обработана как обычный ключ,
//     если он был ранее сохранён под таким именем.
//
// Возвращаемые значения:
//   - string: значение, связанное с ключом, если оно найдено и не истекло.
//     Если значение не найдено или истекло, возвращается пустая строка "".
//   - bool: флаг наличия актуального значения.
//     true — значение найдено и не просрочено;
//     false — значение отсутствует в кэше или срок его действия истёк.
//
// Поведение при граничных случаях:
//   - Если ключ не существует в кэше, функция немедленно возвращает ("", false).
//   - Если ключ существует, но время жизни записи (expires) уже прошло
//     (time.Now().After(e.expires)), запись считается устаревшей,
//     и функция возвращает ("", false). Удаление устаревших записей из памяти
//     не происходит внутри этой функции — очистка может выполняться асинхронно
//     или при следующем обращении к другим методам кэша.
//   - Пустой ключ "" обрабатывается как любой другой ключ: если в кэше есть запись
//     с ключом "", она будет возвращена (при условии, что не истекла).
//
// Примечания:
//   - Функция является потокобезопасной благодаря использованию RWMutex.
//   - Не вызывает паники при любых входных данных.
//   - Не изменяет состояние кэша (только чтение).
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok || time.Now().After(e.expires) {
		return "", false
	}
	return e.value, true
}
```

