Есть несколько подходов:

#### ✅ Рекомендуемый способ: Использовать `@Transactional` в тесте

Если ваш сервис использует транзакции, то и тест должен выполняться в контексте транзакции. Это гарантирует, что сессия будет открыта на протяжении всего теста, включая проверки.

```java
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import static org.junit.jupiter.api.Assertions.assertEquals;

@SpringBootTest
class AccountServiceTest {

    @Autowired
    private AccountService service; // Ваш сервис

    @Autowired
    private AccountRepository accounts; // Или другой компонент для получения баланса

    /**
     * Аннотация @Transactional здесь критически важна!
     * Она оборачивает весь тест в транзакцию, которая НЕ коммитится автоматически,
     * но сохраняет сессию открытой до конца метода.
     * Это позволяет безопасно обращаться к ленивым прокси-объектам.
     */
    @Test
    @Transactional
    void savesInTransaction() {
        // Вызываем бизнес-логику
        service.transfer(a, b, 100);

        // Теперь мы всё ещё внутри той же транзакции/сессии,
        // поэтому можно безопасно читать данные, даже если они ленивые
        assertEquals(900, accounts.balance(a));
    }
}
```

